def article_product_preview(slug):
    is_tent='tent' in slug
    is_event=slug in {'event-layout-software','wedding-layout-planner','tent-layout-software','tent-diagram-software'}
    image='/assets/example-layout.svg' if is_tent else '/assets/event-reception-3d.webp'
    width,height=('720','480') if is_tent else ('1440','1000')
    responsive='' if is_tent else ' srcset="/assets/event-reception-3d-mobile.webp 720w, /assets/event-reception-3d.webp 1440w" sizes="(max-width: 760px) calc(100vw - 30px), (max-width: 1240px) 50vw, 620px"'
    heading='Plan the tent around the entire event.' if is_tent else ('See a complete reception before you plan yours.' if is_event else 'Show customers what their event can become.')
    description='The measured overhead plan keeps guest seating, a 12-foot dance floor and service areas in one view.' if is_tent else 'A furnished example made with the same 3D renderer customers use to understand their layout.'
