def prices():
    data=[('starter','Starter',49,490,'For a rental business testing whether visual requests improve the sales conversation.',['Branded event designer','Catalog and rental prices','Customer designs and quote requests','Business dashboard']),('pro','Pro',99,990,'For businesses that want the branded planning experience tied more closely to their sales workflow.',['Everything in Starter','Custom branding and colors','Deposit collection with Stripe setup','Order and integration workflows']),('commerce','Business',199,1990,'For teams that need more staff access and connected workflow support around customer designs.',['Everything in Pro','Multiple staff accounts','Webhook integrations','Support for connected workflows'])]
    cards=''
